DECLARE
  l_dept_with_rows   employees.department_id%TYPE;
  l_no_match_dept    employees.department_id%TYPE := -1;
  l_expected         NUMBER;
  l_actual           NUMBER;
  l_failures         PLS_INTEGER := 0;

  PROCEDURE check_result(
    p_name        IN VARCHAR2,
    p_expected    IN NUMBER,
    p_actual      IN NUMBER,
    p_note        IN VARCHAR2 DEFAULT NULL
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE('PASS: ' || p_name ||
                           ', expected=' || p_expected ||
                           ', actual=' || p_actual);
    ELSE
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE('FAIL: ' || p_name ||
                           ', expected=' || p_expected ||
                           ', actual=' || p_actual ||
                           CASE WHEN p_note IS NOT NULL THEN ' (' || p_note || ')' END);
    END IF;
  END check_result;

BEGIN
  SAVEPOINT test_block_start;

  -- Check 1: a department_id that has at least one employee row.
  BEGIN
    SELECT department_id
      INTO l_dept_with_rows
      FROM employees
     WHERE department_id IS NOT NULL
       AND ROWNUM = 1;

    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_dept_with_rows;

    l_actual := harness_app.headcount(l_dept_with_rows);

    check_result(
      p_name     => 'headcount with matching department_id',
      p_expected => l_expected,
      p_actual   => l_actual
    );
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE('FAIL: headcount with matching department_id - no non-NULL department_id row found in employees');
  END;

  -- Check 2: a non-NULL department_id that matches no employee row.
  BEGIN
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_no_match_dept;

    IF l_expected = 0 THEN
      l_actual := harness_app.headcount(l_no_match_dept);

      check_result(
        p_name     => 'headcount with non-NULL unmatched department_id',
        p_expected => 0,
        p_actual   => l_actual
      );
    ELSE
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE('FAIL: headcount with non-NULL unmatched department_id - candidate ' ||
                           l_no_match_dept ||
                           ' is present in employees, so no suitable unmatched value was found');
    END IF;
  END;

  -- Check 3: NULL argument.
  -- The function compares department_id = p_department_id.
  -- In SQL, department_id = NULL matches no row, even when department_id IS NULL.
  BEGIN
    l_actual := harness_app.headcount(NULL);

    check_result(
      p_name     => 'headcount with NULL argument',
      p_expected => 0,
      p_actual   => l_actual
    );
  END;

  ROLLBACK TO test_block_start;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'headcount test block failed: ' || l_failures || ' check(s) failed');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK TO test_block_start;
    DBMS_OUTPUT.PUT_LINE('FAIL: unexpected error: ' || SQLERRM);
    RAISE;
END;
/
```

This block covers three checks:

1. A `department_id` taken from `employees` where the value is not null, with the expected count computed independently by a separate `COUNT(*)` query using the same equality condition. If no such row exists, the setup prints `FAIL` and counts as a failure.
2. A non-null candidate unmatched value, `-1`, confirmed by querying `employees` first. If `-1` is present in `employees`, the check prints `FAIL` because no suitable unmatched non-null value was found in this test setup.
3. A `NULL` argument. Because the function uses `department_id = p_department_id`, a null bind matches no rows, so the expected result is the function’s no-match result, `0`.

I have not run this block.

